  Summary: Reshape climate table by detecting header row inside sheet, set proper column names, drop preamble rows, and coerce numeric columns.
  Code: def process(climate):
    import pandas as pd
    import numpy as np

    df = climate.copy()

    # Drop fully empty rows
    df = df.dropna(how='all')

    # Find the header row: the first row with at least 5 non-null cells (typical for header)
    nn = df.notna().sum(axis=1)
    header_idx = nn[nn >= 5].index.min()
    if pd.isna(header_idx):
        header_idx = df.index.min()

    header = df.loc[header_idx].astype(str).str.strip().tolist()
    data = df.loc[df.index > header_idx].copy()
    data.columns = header

    # Clean colnames
    data.columns = (
        pd.Index(data.columns)
        .astype(str)
        .str.replace(r'\s+', ' ', regex=True)
        .str.strip()
    )

    # Coerce numeric where possible
    for c in data.columns:
        data[c] = pd.to_numeric(data[c], errors='ignore')

    return data
