def process(climate_files):
    import pandas as pd, numpy as np
    path = climate_files['path'].iloc[0]
    raw = pd.read_excel(path, sheet_name=0, header=None)

    def norm(x):
        if pd.isna(x):
            return ''
        return str(x).strip().lower()

    # find header row: look for 'al' and 'age'/'year'
    header_idx = None
    for i in range(min(200, len(raw))):
        row = [norm(v) for v in raw.iloc[i].tolist()]
        joined = ' '.join([r for r in row if r])
        if ('al' in joined or 'aluminum' in joined) and (('year' in joined) or ('age' in joined) or ('ka' in joined) or ('kyr' in joined)):
            header_idx = i
            break
    if header_idx is None:
        # fallback: first row where at least 8 cells are strings (likely header)
        for i in range(min(200, len(raw))):
            s = raw.iloc[i]
            nstr = sum([isinstance(v, str) and v.strip() != '' for v in s.tolist()])
            if nstr >= 5:
                header_idx = i
                break
    if header_idx is None:
        return pd.DataFrame({'error':['Could not locate header row']})

    header = raw.iloc[header_idx].tolist()
    cols = []
    for j,h in enumerate(header):
        name = str(h).strip() if not pd.isna(h) else f'col{j}'
        cols.append(name)
    df = raw.iloc[header_idx+1:].copy()
    df.columns = cols

    # identify age/year column
    col_norm = {c: norm(c) for c in df.columns}
    age_candidates = [c for c,nc in col_norm.items() if any(k in nc for k in ['year','age','ka','kyr'])]
    if not age_candidates:
        age_candidates = [df.columns[0]]
    age_col = age_candidates[0]

    # identify aluminum column
    al_candidates = [c for c,nc in col_norm.items() if ('al' == nc or nc.startswith('al ') or 'aluminum' in nc or nc.endswith(' al') or 'al (ppm' in nc or nc.endswith('(ppm)'))]
    # avoid picking 'cal' etc.
    al_candidates = [c for c in al_candidates if 'cal' not in col_norm[c]]
    if not al_candidates:
        # heuristic: column with large numeric ppm-like values among numeric columns
        num_test = df.apply(pd.to_numeric, errors='coerce')
        means = num_test.mean(numeric_only=True)
        if len(means)==0:
            return pd.DataFrame({'error':['No numeric columns found']})
        al_col = means.sort_values(ascending=False).index[0]
    else:
        al_col = al_candidates[0]

    out = pd.DataFrame({
        'age_raw': pd.to_numeric(df[age_col], errors='coerce'),
        'aluminum': pd.to_numeric(df[al_col], errors='coerce')
    }).dropna(subset=['age_raw','aluminum'])

    # Convert age to "year" scale: if looks like Ma/ka then convert to years BP rounded
    # If max age_raw < 1000 assume it's in Ma or ka. In this file values like 0.78 suggest Ma.
    if out['age_raw'].max() < 1000:
        # treat as Ma (million years)
        out['year'] = (out['age_raw'] * 1_000_000).round().astype('int64')
    elif out['age_raw'].max() < 10_000:
        # treat as years already
        out['year'] = out['age_raw'].round().astype('int64')
    else:
        out['year'] = out['age_raw'].round().astype('int64')

    return out[['year','aluminum']]

